PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN (0,1)), phone TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', state_json TEXT NOT NULL DEFAULT '{"cart":[],"favorites":[]}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id,created_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('premium','fold','value')), tag TEXT NOT NULL DEFAULT '', price_cents INTEGER NOT NULL CHECK(price_cents>0), storage TEXT NOT NULL, spec TEXT NOT NULL, features_json TEXT NOT NULL, color TEXT NOT NULL DEFAULT '#909ba7', stock INTEGER NOT NULL DEFAULT 20 CHECK(stock>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), sort_order INTEGER NOT NULL DEFAULT 100, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS products_active ON products(active,sort_order,id);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, items_json TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>0), status TEXT NOT NULL DEFAULT 'recibida' CHECK(status IN ('recibida','en_revision','confirmada','cancelada')), note TEXT NOT NULL DEFAULT '', idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS orders_user_date ON orders(user_id,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS users_disabled ON users(disabled);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rate_limits_expiry ON rate_limits(expires_at);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);

